import { extract } from './extract-util.js';
import { globalSprinkles } from './safe-sprinkles.js';
import {
  AlignContentPositionProps,
  AlignItemsPositionProps,
  AlignSelfPositionProps,
  JustifyContentPositionProps,
  JustifyItemsPositionProps,
  JustifySelfPositionProps,
  PlaceContentPositionProps,
  PlaceItemsPositionProps,
  PlaceSelfPositionProps,
} from './sprinkle-properties.js';

export interface GridFlexPositionProps {
  justifySelf?: JustifySelfPositionProps;
  alignSelf?: AlignSelfPositionProps;
  placeSelf?: PlaceSelfPositionProps;
  justifyItems?: JustifyItemsPositionProps;
  alignItems?: AlignItemsPositionProps;
  placeItems?: PlaceItemsPositionProps;
  justifyContent?: JustifyContentPositionProps;
  alignContent?: AlignContentPositionProps;
  placeContent?: PlaceContentPositionProps;
}

const gridFlexPositionPropKeys: Array<keyof GridFlexPositionProps> = [
  'justifySelf',
  'alignSelf',
  'placeSelf',
  'justifyItems',
  'alignItems',
  'placeItems',
  'justifyContent',
  'alignContent',
  'placeContent',
];

/** Given a set of props, this function will extract the sprinkles props for
 * Grid/Flex Position spinkles and return the appropriate
 * classnames as well as the remaining props. */
export function getGridFlexPositionSprinkles<T extends GridFlexPositionProps>(
  props: T,
  defaults: Partial<GridFlexPositionProps> = {},
): [
  sprinklesClassNames: string,
  remainingProps: Omit<T, keyof GridFlexPositionProps>,
] {
  const { extracted, rest } = extract(props, gridFlexPositionPropKeys);
  const { extracted: extractedDefaults } = extract(
    defaults,
    gridFlexPositionPropKeys,
  );

  return [globalSprinkles({ ...extractedDefaults, ...extracted }), rest];
}
